"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["82445"],{86921(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.grupo_area_enem_snapshot.codigo_obrigatorio","status":422,"titulo":"C\xf3digo do grupo de \xe1rea do ENEM \xe9 obrigat\xf3rio"},"descricao":{"codigo":"uniplus.selecao.grupo_area_enem_snapshot.codigo_obrigatorio","requisitos":[],"oQueAconteceu":["O grupo de \xe1rea do ENEM que o processo congelaria chegou sem c\xf3digo, ou com o c\xf3digo em branco.","Cada oferta da distribui\xe7\xe3o de vagas e cada grupo do quadro de pesos por \xe1rea da classifica\xe7\xe3o\\nguardam uma c\xf3pia do grupo de \xe1rea do ENEM do curso, com c\xf3digo e r\xf3tulo, congelada com o processo.\\nO c\xf3digo \xe9 a identidade do grupo (\xe9 por ele que o processo casa a oferta com a linha de Pesos por\\n\xc1rea), e o r\xf3tulo \xe9 o que o edital publicado mostra. Editar o curso depois n\xe3o alcan\xe7a o processo;\\nquem quiser o grupo novo redefine a distribui\xe7\xe3o de vagas ou a classifica\xe7\xe3o.","O grupo vem do cadastro de Configura\xe7\xe3o, que s\xf3 aceita os quatro grupos do Anexo I da Resolu\xe7\xe3o\\nn\xba 805/2024/Consepe (Tecnol\xf3gica, Human\xedstica I, Human\xedstica II e Sa\xfade e Biol\xf3gicas) e p\xf5e o c\xf3digo e o\\nr\xf3tulo de cada um. Um curso que n\xe3o declara grupo n\xe3o gera esta recusa: a aus\xeancia \xe9 v\xe1lida.","Na distribui\xe7\xe3o de vagas a recusa vem no campo `distribuicaoVagas[<\xedndice>].grupoAreaEnem` e\\nacumula, na mesma resposta, com as demais viola\xe7\xf5es da distribui\xe7\xe3o. Na classifica\xe7\xe3o vem no campo\\n`resolucaoPesoAreaEnem`, junto das demais viola\xe7\xf5es do quadro de pesos.","Esta confer\xeancia vem antes da do r\xf3tulo ([`rotulo_obrigatorio`](/erros/uniplus.selecao.grupo_area_enem_snapshot.rotulo_obrigatorio)).\\nNa releitura da configura\xe7\xe3o congelada, o c\xf3digo em branco j\xe1 \xe9 recusado antes, como [`envelope_malformado`](/erros/uniplus.selecao.envelope_codec.envelope_malformado),\\ne esta causa n\xe3o aparece."],"comoResolver":["Corrija o grupo de \xe1rea do ENEM no cadastro de Configura\xe7\xe3o (o do curso da oferta, ou o da linha de\\nPesos por \xc1rea da resolu\xe7\xe3o declarada), para um dos quatro grupos, e envie de novo a defini\xe7\xe3o da\\ndistribui\xe7\xe3o de vagas ou da classifica\xe7\xe3o. O c\xf3digo e o r\xf3tulo s\xe3o postos pelo cadastro: o\\ngrupo que chega sem eles, ou com texto fora do esperado, indica dado gravado por caminho que n\xe3o\\npassou por ele, e a causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo","Simula\xe7\xe3o da distribui\xe7\xe3o de vagas do processo seletivo","Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Grupo area enem snapshot"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);